<script module lang="ts">
/**
 * A radar chart profiling items over shared-unit axes (`design/components/radar-chart.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/radar-chart.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import {
  DEFAULT_CHART_MESSAGES,
  Icon,
  UNMEASURED,
  agentMember,
  chartHiddenSeries,
  chartMarks,
  chartPosition,
  chartSeries,
  chooseChartMark,
  createReading,
  createWarningLog,
  devWarning,
  joinSlot,
  measureBox,
  nearest2D,
  radarChartModel,
  radarChartReadout,
  radarChartSelection,
  readChartCap,
  readChartPosition,
  readingRest,
  readingView,
  toggleChartSeries,
  toggleSeries,
  watchEffect,
  type ChartMessages,
  type ChartSeries,
  type ChartTooltipConfig,
  type RadarAxis,
  type ValueFormat,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/charts/radar-chart.module.css'
import a11y from '@polymorph/recipes/conventions/a11y.module.css'
import chartFrame from '@polymorph/recipes/charts/frame/chart-frame.module.css'
import chartLegend from '@polymorph/recipes/charts/frame/chart-legend.module.css'
import chartTooltip from '@polymorph/recipes/charts/frame/chart-tooltip.module.css'
import chartTwin from '@polymorph/recipes/charts/frame/chart-twin.module.css'
import Button from '../controls/Button.svelte'
import Table from '../structure/Table.svelte'
import TableBody from '../structure/TableBody.svelte'
import TableCell from '../structure/TableCell.svelte'
import TableHead from '../structure/TableHead.svelte'
import TableHeader from '../structure/TableHeader.svelte'
import TableRow from '../structure/TableRow.svelte'

export interface RadarChartProps {
  /**
   * The spokes, **3–6**, drawn clockwise from 12 o'clock in the given order. Fewer than 3 raises
   * a dev warning, because two values read better side by side; more than 6 raises one, because
   * the polygon becomes unreadable. The chart still draws every axis it is given, because a
   * warning never hides data.
   */
  axes: readonly RadarAxis[]
  /**
   * **One row per axis, in the axes' order**; row *i* binds to `axes[i]`. A count mismatch
   * raises a dev warning naming both lengths. Each row has one field per series key, and `null`
   * is a **gap**: the polygon breaks at that vertex instead of dipping to zero.
   */
  data: readonly Readonly<Record<string, string | number | null>>[]
  /**
   * Formats values in the tooltip and twin. There is no `y` prop: the one shared scale runs from
   * zero to the nice'd maximum across **all** series and axes, and nothing is configurable per
   * axis.
   */
  format?: ValueFormat
  /**
   * The accessible name.
   */
  label: string
  /**
   * Shows the previous frame at reduced opacity during a refetch.
   */
  loading?: boolean
  /**
   * The locale for `Intl` formatting.
   */
  locale?: string
  /**
   * The chart tier's string catalog (`ChartMessages`). Defaults to generic English; a localized
   * host passes the same object to every chart.
   */
  messages?: ChartMessages
  /**
   * Called with the axis key, series key and value at the reading position, on Enter, Space or
   * click.
   */
  onSelect?: (selection: { axis: string; key: string; value: number }) => void
  /**
   * The polygons, **at most the palette's cap**. Polygons can cross anywhere, so
   * `--pm-chart-cap` limits them as it limits Scatter.
   */
  series: readonly ChartSeries[]
  /**
   * The chart size; the outer radius fits the plot's shorter side, as in DonutChart.
   */
  size?: 'sm' | 'md' | 'lg'
  /**
   * The per-vertex readout: an axis label header (`hideLabel` removes it), then the series key
   * glyph, series label and formatted value.
   */
  tooltip?: false | ChartTooltipConfig
}
</script>

<script lang="ts">
let {
  axes,
  data,
  format,
  label: labelOwn,
  loading = false,
  locale,
  messages = (() => DEFAULT_CHART_MESSAGES)(),
  onSelect,
  series,
  size = 'md',
  tooltip = (() => ({}))(),
}: RadarChartProps = $props()
const joined = joinSlot(undefined, () => ({ label: labelOwn, size: size }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
const listening = {
  get select() {
    return onSelect !== undefined
  },
}
let box = $state(UNMEASURED)
let reading = $state(createReading({ count: 0, seriesStart: 0 }))
let position = $state(readingRest(0))
let hidden = $state(new Set<string>())
let twinOpen = $state(false)
let warningLog = $state(createWarningLog())
let cap = $state(readChartCap(null))
let frame = $state<HTMLElement | null>(null)
let plot = $state<HTMLElement | null>(null)
const input = $derived({
  axes,
  data,
  series,
  format,
  label,
  locale,
  messages,
  tooltip,
  loading,
  selectable: listening.select,
  hidden,
  cap,
  box,
})
const model = $derived(radarChartModel(input))
const view = $derived(readingView(position, axes.length, model.visible.length))
const readout = $derived(radarChartReadout(input, model, view))
const walked = $derived(view.series ?? 0)
const activate = $derived(() => {
  const selection = radarChartSelection(input, model, reading.now())
  if (selection !== null) onSelect?.(selection)
})
const walk = $derived({
  count: axes.length,
  seriesCount: model.visible.length,
  walkSeries: true,
  seriesStart: 0,
  wrap: true,
})
const marks = $derived({
  walk,
  input,
  model,
  readout: radarChartReadout,
  selection: radarChartSelection,
})
const onKey = $derived((event: KeyboardEvent) => {
  if (listening.select && (event.key === 'Enter' || event.key === ' ')) {
    event.preventDefault()
    activate()
    return
  }
  reading.update(walk)
  if (reading.key(event.key)) event.preventDefault()
})
const onPointer = $derived((event: PointerEvent) => {
  if (model.plot === null) return
  const rect = (event.currentTarget as Element).getBoundingClientRect()
  const hit = nearest2D(model.positions, event.clientX - rect.left, event.clientY - rect.top)
  if (hit === -1) {
    reading.clear()
    return
  }
  reading.moveTo(hit % axes.length, Math.floor(hit / axes.length))
})
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const run = () => {
    box = plot === null ? box : measureBox(plot, box)
  }
  const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
  for (const element of [plot]) if (element) resize?.observe(element)
  release1 = () => {
    resize?.disconnect()
  }
  run()
}
watchEffect(effect1)
onDestroy(() => release1?.())
const effect2 = () => {
  reading.subscribe((now) => {
    position = now
  })
}
watchEffect(effect2)
const effect3 = () => {
  warningLog.log(model.warnings, (message) => devWarning(true, message))
}
watchEffect(effect3, { watch: () => model.warnings.join('\n') })
const effect4 = () => {
  cap = model.state === 'empty' ? cap : readChartCap(plot)
}
watchEffect(effect4, { watch: () => model.state === 'empty' })
let release5: (() => void) | undefined
const effect5 = () => {
  release5?.()
  const ran =
    !listening.select && !model.legend
      ? () => {}
      : agentMember({
          member: 'RadarChart',
          element: () => frame,
          state: () => ({
            items: listening.select ? chartMarks(marks, reading) : [],
            position: chartPosition(marks, reading),
            count: walk.count,
            series: chartSeries(frame, chartLegend.key, model.painted),
            hidden: chartHiddenSeries(frame, chartLegend.key, model.painted),
          }),
          actions: {
            read: { argument: 'number', run: (value) => readChartPosition(marks, value, reading) },
            choose: {
              argument: 'id',
              among: 'items',
              run: (value) => chooseChartMark(marks, value, reading, activate),
            },
            toggle: {
              argument: 'id',
              among: 'series',
              run: (value) => toggleChartSeries(frame, chartLegend.key, model.painted, value),
            },
          },
        })
  release5 = () => {
    ran()
  }
}
watchEffect(effect5)
onDestroy(() => release5?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<figure
    bind:this={frame}
    class={chartFrame.frame}
    data-size={size}
    data-state={model.state}
    data-position={view.active ? view.index : undefined}
    aria-label={label}
    data-member="radar-chart"
    ><div class={chartFrame.region}
      ><div class={chartFrame.yAxis}></div
      ><div bind:this={plot} class={chartFrame.plot}
        >{#if model.state === 'empty'
          }<div class={chartFrame.empty}><span>{messages.empty}</span></div
        >{:else
          }<div
            class={styles.surface}
            tabindex="0"
            role="img"
            aria-label={label}
            onkeydown={(event) => { onKey(event) }}
            onclick={() => { activate() }}
            onpointermove={(event) => { onPointer(event) }}
            onpointerleave={() => { reading.clear() }}
            onblur={() => { reading.clear() }}
            >{#if model.plot !== null
              }<svg
                class={styles.marks}
                data-reading={(view.active) ? '' : undefined}
                width={model.plot?.width}
                height={model.plot?.height}
                aria-hidden="true"
                focusable="false"
                ><g transform={model.plot?.transform}
                  ><g class={styles.grid}
                    >{#each model.plot?.grid ?? [] as line (line.key)}<path d={line.d}></path>{/each
                  }</g
                  ><g class={styles.profiles}
                    >{#each model.plot?.profiles ?? [] as profile (profile.key)
                      }<g
                        style:--pm-chart-mark={profile.paint}
                        data-active={(view.active && walked === profile.series) ? '' : undefined}
                        ><path class={styles.wash} d={profile.d}></path
                        ><path class={styles.stroke} d={profile.d}></path
                        >{#each profile.vertices as vertex (vertex.key)
                          }<circle
                            class={styles.vertex}
                            cx={vertex.x}
                            cy={vertex.y}
                            r={vertex.r}
                            data-active={(view.index === vertex.index && walked === profile.series) ? '' : undefined}
                          ></circle
                        >{/each
                      }</g
                    >{/each
                  }</g
                  ><g class={styles.labels}
                    >{#each model.plot?.labels ?? [] as spoke (spoke.key)
                      }<text x={spoke.x} y={spoke.y} text-anchor={spoke.anchor}>{spoke.text}</text
                    >{/each
                  }</g
                ></g
              ></svg
            >{/if
          }</div
        >{/if
        }{#if readout.tooltip !== null
          }<div
            class={chartTooltip.tooltip}
            style:--pm-chart-tip-x={`${readout.tooltip?.x}px`}
            style:--pm-chart-tip-y={`${readout.tooltip?.y}px`}
            data-indicator={readout.tooltip?.indicator}
            data-side={readout.tooltip?.side}
            aria-hidden="true"
            >{#if readout.tooltip?.header !== undefined
              }<p class={chartTooltip.header}>{readout.tooltip?.header}</p
            >{/if
            }<ul class={chartTooltip.rows}
              >{#each readout.tooltip?.rows ?? [] as row (row.key)
                }<li class={chartTooltip.row}
                  ><span class={chartTooltip.key} style:--pm-chart-key={row.paint}></span
                  ><span class={chartTooltip.value}>{row.value}</span
                  ><span class={chartTooltip.label}>{row.label}</span
                ></li
              >{/each
            }</ul
          ></div
        >{/if
      }</div
      ><div class={chartFrame.xAxis}></div
    ></div
    >{#if model.legend
      }{#if model.painted.length > 0
        }<ul class={styles.legend} data-key-shape="line"
          >{#each model.painted as entry (entry.key)
            }<li class={chartLegend.item}
              ><button
                class={chartLegend.key}
                type="button"
                aria-pressed={hidden.has(entry.key) ? 'false' : 'true'}
                onclick={() => { hidden = toggleSeries(hidden, entry.key) }}
                ><span
                  class={chartLegend.swatch}
                  style:--pm-chart-key={entry.paint}
                  aria-hidden="true"
                ></span
                >{#if entry.icon !== undefined
                  }<span class={chartLegend.glyph}><Icon name={entry.icon} size="sm" /></span
                >{/if
                }<span class={chartLegend.label}>{entry.label}</span
              ></button
            ></li
          >{/each
        }</ul
      >{/if
    }{/if
    }<span class={a11y.visuallyHidden}>{model.summary}</span
    ><div class={chartTwin.twin} data-state={twinOpen ? 'open' : 'closed'}
      ><div class={chartTwin.toggle}
        ><Button
          variant="ghost"
          tone="neutral"
          size="sm"
          icon="table"
          iconOnly={true}
          label={twinOpen ? messages.hideTable(label) : messages.showTable(label)}
          onClick={() => { twinOpen = !twinOpen }}
      /></div
      >{#if twinOpen
        }<div class={chartTwin.table}
          ><Table label={messages.tableLabel(label)} caption={messages.tableLabel(label)}
            ><TableHead
              ><TableRow
                >{#each model.twin.columns as column (column.key)
                  }<TableHeader numeric={column.numeric}>{column.label}</TableHeader
                >{/each
              }</TableRow
            ></TableHead
            ><TableBody
              >{#each model.twin.rows as row, line (line)
                }<TableRow
                  >{#each row as cell, cellIndex (model.twin.columns[cellIndex]?.key ?? cellIndex)
                    }<TableCell numeric={model.twin.columns[cellIndex]?.numeric}
                      >{cell === '' ? '—' : cell
                    }</TableCell
                  >{/each
                }</TableRow
              >{/each
            }</TableBody
          ></Table
        ></div
      >{/if
    }</div
    ><span class={a11y.visuallyHidden}
      ><div aria-live="polite" aria-atomic="true">{readout.announcement}</div
    ></span
  ></figure
>{/if
}{@render joined.end?.()}
